{"version":3,"file":"decluttering-card-plus.report-try-box-Bh4xX1eu.js","sources":["../src/report-try.ts","../src/report-try-box.ts"],"sourcesContent":["import { PlaygroundResult, tryPlaceholderWith } from './playground';\nimport { redact, SECRET_NAME, secretValues } from './report';\nimport { BuildTrace, ItemTrace, itemTitle, SectionEvaluate, TraceReport } from './trace';\n\n/* eslint-disable @typescript-eslint/no-explicit-any */\n\n/*\n * Try a placeholder in the report (#376): type one in and see what it gives, read against\n * one build of the report - the card, a copy of a repeat, a card nested inside, or one item\n * template's fill. Which one is the scope: the same name can mean something different in\n * each, and that is often the very thing being chased.\n */\nexport interface TryScope {\n  label: string;\n  evaluate: SectionEvaluate;\n  /** An item template's fill: its values are its variables. */\n  values?: Record<string, unknown>[];\n  /** Placeholders to offer: each variable on its own, then each the build met. */\n  offered: string[];\n}\n\n/** Every build in the report a placeholder can be tried against, the card's own first. */\nexport function tryScopes(reports: TraceReport[], hass?: any): TryScope[] {\n  const scopes: TryScope[] = [];\n  const offer = (names: string[], trace: BuildTrace): string[] => [\n    ...new Set([...names.map((name) => `[[${name}]]`), ...trace.placeholders.keys()]),\n  ];\n  const items = (list: ItemTrace[] | undefined, base: string, evaluate: SectionEvaluate): void => {\n    for (const item of list ?? []) {\n      const label = `${base} › ${itemTitle(item, hass)}`;\n      const values = [...(item.trace.values ?? [])].map(([name, value]) => ({ [name]: value }));\n      scopes.push({\n        label,\n        evaluate,\n        values,\n        offered: offer([...(item.trace.values ?? []).keys()].map(String), item.trace),\n      });\n      items(item.trace.items, label, evaluate);\n    }\n  };\n  for (const report of reports) {\n    const card = [...report.chain, report.label].join(' › ');\n    for (const section of report.sections) {\n      if (!section.evaluate) continue;\n      const label = section.label ? `${card} › ${section.label}` : card;\n      const names = section.variables.map((row) => row.variable);\n      scopes.push({ label, evaluate: section.evaluate, offered: offer(names, section.trace) });\n      items(section.trace.items, label, section.evaluate);\n    }\n  }\n  return scopes;\n}\n\n// Every variable a piece of text asks for, in a nested placeholder or a step's argument too.\nconst ASKED_FOR = /\\[\\[\\s*([^[\\]|?]+)/g;\n\n/*\n * What the box shows for one placeholder in one scope, redacted as the report is: a secret\n * named in it hides every value outright - a step that only changes its case would still say\n * it - and anything else has the report's own rules run over it, the known secrets included,\n * so a variable built out of a password does not give it away either.\n */\nexport function tryInReport(\n  scope: TryScope,\n  expression: string,\n  reports: TraceReport[],\n  redacting: boolean,\n): PlaygroundResult {\n  const result = tryPlaceholderWith(\n    (content, onMissing) => scope.evaluate(content, onMissing, scope.values),\n    expression,\n  );\n  if (!redacting) return result;\n  const asked: string[] = expression.match(ASKED_FOR) ?? [];\n  const secret = asked.some((each) => SECRET_NAME.test(each.slice(2).trim()));\n  const secrets = secret ? [] : secretValues(reports);\n  const hide = (value: unknown): unknown => {\n    if (value === undefined) return value;\n    if (secret) return '<redacted>';\n    if (typeof value === 'string') return redact(value, secrets);\n    if (value === null) return value;\n    // A number can be a secret too: a PIN of 1234 is in the known secrets as text.\n    const text = typeof value === 'object' ? JSON.stringify(value) : String(value);\n    const cleaned = redact(text, secrets);\n    return cleaned === text ? value : cleaned;\n  };\n  return {\n    ...result,\n    steps: result.steps.map((step) => ({ ...step, value: hide(step.value) })),\n    whole: { ...result.whole, value: hide(result.whole.value) },\n    inText: result.inText === undefined ? undefined : (hide(result.inText) as string),\n  };\n}\n","import { html, TemplateResult, nothing } from 'lit';\nimport { property, state } from 'lit/decorators.js';\nimport { FormSchemaEntry } from './types';\nimport { PlaygroundResult } from './playground';\nimport { DeclutteringPlaceholderTool } from './template-editor/placeholder-tool';\nimport { TryScope, tryInReport, tryScopes } from './report-try';\nimport { TraceReport } from './trace';\nimport { localize } from './localize';\n\n/*\n * The report view's Try a placeholder box (#376): the template editor's tool, with a scope\n * picker in place of the example strip. The scopes are the builds in the report - the card,\n * each copy of a repeat, each card nested inside and each item template's fill - and what is\n * typed in is built the way that build was, against Home Assistant as it is now. Loaded only\n * when a report is on show, so a dashboard without one never downloads it.\n */\nexport class DeclutteringReportTry extends DeclutteringPlaceholderTool {\n  @property({ attribute: false }) public reports: TraceReport[] = [];\n  /** `redact: false` on the card: values are shown as they are. */\n  @property({ attribute: false }) public unredacted = false;\n\n  @state() private _scope = 0;\n\n  private _scopesFor?: { reports: TraceReport[]; scopes: TryScope[] };\n\n  private get _scopes(): TryScope[] {\n    if (this._scopesFor?.reports !== this.reports) {\n      this._scopesFor = { reports: this.reports, scopes: tryScopes(this.reports, this.hass) };\n    }\n    return this._scopesFor.scopes;\n  }\n\n  private get _current(): TryScope | undefined {\n    const scopes = this._scopes;\n    return scopes[Math.min(this._scope, scopes.length - 1)];\n  }\n\n  protected render(): TemplateResult {\n    const scopes = this._scopes;\n    const scope = this._current;\n    if (!scope || !this.hass) return html``;\n    const t = (key: string, params?: Record<string, unknown>): string => localize(key, params, this.hass);\n    const value = this._expression || scope.offered[0] || '';\n    const schema: FormSchemaEntry[] = [\n      {\n        name: 'scope',\n        label: t('report_try.scope'),\n        selector: {\n          select: {\n            mode: 'dropdown',\n            options: scopes.map((each, index) => ({ value: String(index), label: each.label })),\n          },\n        },\n      },\n      {\n        name: 'placeholder',\n        label: t('placeholder_tool.placeholder'),\n        selector: {\n          select: {\n            mode: 'dropdown',\n            custom_value: true,\n            options: scope.offered.map((each) => ({ value: each, label: each })),\n          },\n        },\n      },\n    ];\n    return html`\n      <ha-expansion-panel outlined>\n        <span slot=\"header\">${t('placeholder_tool.header')}</span>\n        <div style=\"padding: 12px 4px 4px\">\n          <p class=\"hint\">${t('report_try.hint')}</p>\n          <ha-form\n            .hass=${this.hass}\n            .data=${{ scope: String(scopes.indexOf(scope)), placeholder: value }}\n            .schema=${schema}\n            .computeLabel=${(s: FormSchemaEntry): string => s.label ?? s.name}\n            @value-changed=${this._picked}\n          ></ha-form>\n          ${this._renderChips(value)} ${value ? this._renderResult(value) : nothing}\n        </div>\n      </ha-expansion-panel>\n    `;\n  }\n\n  protected _result(expression: string): PlaygroundResult | undefined {\n    const scope = this._current;\n    if (!scope) return undefined;\n    try {\n      return tryInReport(scope, expression, this.reports, !this.unredacted);\n    } catch {\n      return undefined;\n    }\n  }\n\n  protected _picked(ev: CustomEvent): void {\n    ev.stopPropagation();\n    const data = ev.detail.value as { scope?: string; placeholder?: string };\n    // The placeholder stays when the scope changes: the same one in another build is often the question.\n    this._scope = Number(data.scope ?? this._scope);\n    this._expression = typeof data.placeholder === 'string' ? data.placeholder : '';\n  }\n}\n\nexport const REPORT_TRY_TAG = 'decluttering-report-try';\nif (!customElements.get(REPORT_TRY_TAG)) customElements.define(REPORT_TRY_TAG, DeclutteringReportTry);\n"],"names":["tryScopes","reports","hass","scopes","offer","names","trace","Set","map","name","placeholders","keys","items","list","base","evaluate","item","label","itemTitle","values","_a","value","push","offered","_b","String","report","card","chain","join","section","sections","variables","row","variable","ASKED_FOR","DeclutteringReportTry","DeclutteringPlaceholderTool","constructor","this","unredacted","_scope","_scopes","_scopesFor","_current","Math","min","length","render","scope","html","t","key","params","localize","_expression","schema","selector","select","mode","options","each","index","custom_value","indexOf","placeholder","s","_picked","_renderChips","_renderResult","nothing","_result","expression","redacting","result","tryPlaceholderWith","content","onMissing","secret","match","some","SECRET_NAME","test","slice","trim","secrets","secretValues","hide","undefined","redact","text","JSON","stringify","cleaned","Object","assign","steps","step","whole","inText","tryInReport","ev","stopPropagation","data","detail","Number","__decorate","property","attribute","prototype","state","REPORT_TRY_TAG","customElements","get","define"],"mappings":"kNAsBM,SAAUA,EAAUC,EAAwBC,GAChD,MAAMC,EAAqB,GACrBC,EAAQ,CAACC,EAAiBC,IAAgC,IAC3D,IAAIC,IAAI,IAAIF,EAAMG,IAAKC,GAAS,KAAKA,UAAcH,EAAMI,aAAaC,UAErEC,EAAQ,CAACC,EAA+BC,EAAcC,aAC1D,IAAK,MAAMC,KAAQH,QAAAA,EAAQ,GAAI,CAC7B,MAAMI,EAAQ,GAAGH,OAAUI,EAAUF,EAAMd,KACrCiB,EAAS,IAAsB,UAAjBH,EAAKV,MAAMa,kBAAMC,EAAAA,EAAI,IAAKZ,IAAI,EAAEC,EAAMY,MAAM,CAAQZ,CAACA,GAAOY,KAChFlB,EAA